import numpy as np

# Note: All docstrings were generated by Claude (Anthropic) Sonnet 3.7, April 2025

def gaussian_design(BT, samples_per_symbol, span, normalize=True):
    """
    Create a Gaussian filter for GMSK modulation with normalized frequency. Based on GSM spec (https://www.etsi.org/deliver/etsi_ts/100900_100999/100959/08.04.00_60/ts_100959v080400p.pdf)

    Note: This function was generated with assistance from Claude (Anthropic) Sonnet 3.7 & Google AI (Gemini 2.5 Pro), April 2025
    
    Parameters
    ----------
    BT : float
        Bandwidth-Time product (typically 0.3 for GMSK)
    samples_per_symbol : int
        Number of samples per symbol
    span : int
        Filter span in symbol periods
    normalize: bool
        Whether or not to normalize filter to unit energy. Default is True.
    
    Returns
    -------
    numpy.ndarray
        Gaussian filter coefficients
    """
    
    # Check if BT is positive
    if BT <= 0:
        raise ValueError("Error gaussian_design.py: Bandwidth time product must be positive")

    # Check if span is at least 1
    elif (span < 1):
        raise ValueError('Error gaussian_design.py: Span must be greater than or equal to 1')

    # Check if span is an integer 
    elif not isinstance(span, int):
        raise TypeError('Error gaussian_design.py: Span must be an integer')

    # Check if samples per symbol is greater than 1
    if (samples_per_symbol <= 1):
        raise ValueError('Error gaussian_design.py: Samples per symbol must be greater than 1')

    # Check if samples per symbol is an integer
    elif not isinstance(samples_per_symbol, int):
        raise TypeError('Error gaussian_design.py: Samples per symbol must be an integer')
    
    # Calculate filter length (in samples)
    filter_length = samples_per_symbol * span
    
    # Ensure filter length is odd
    if filter_length % 2 == 0:
        filter_length += 1
    
    # Time base centered at zero (normalized by symbol duration)
    t = np.arange(-(filter_length//2), filter_length//2 + 1) / samples_per_symbol

    T = samples_per_symbol
    
    # Standard deviation of the Gaussian pulse (normalized)
    sigma = np.sqrt(np.log(2)) / (2 * np.pi * BT)
    
    # Gaussian pulse (without PDF normalization factor)
    h = np.exp(-(t**2)/(2*sigma**2)) 

    if normalize:
        h = h/(np.sqrt(2*np.pi) * sigma * T)
    
    return np.convolve(h, np.ones(T)/T)

def rectangular_design(span, normalize=True):
    """
    Design a rectangular pulse shaping filter.
    
    Creates a rectangular (flat) filter impulse response with the specified span
    and normalized to unit energy.
    
    Parameters
    ----------
    span : int
        The number of samples in the rectangular filter
    normalize: bool
        Whether or not to normalize filter to unit energy. Default is True.
        
    Returns
    -------
    numpy.ndarray
        Normalized rectangular filter weights with unit energy
    """

    # Check if span is at least 1
    if (span < 1):
        raise ValueError('Error rectangular_design.py: Span must be greater than or equal to 1')

    # Check if span is an integer 
    elif not isinstance(span, int):
        raise TypeError('Error rectangular_design.py: Span must be an integer')
    
    weights = np.ones(span)

    if normalize:
        weights = weights/np.sum(weights)

    return weights


